SharedAccuracyCertificateDraft.Certificate.projected_input_exists {m : ℕ}
  {family : NumStability.DirectionalLine.LineFamily m} {q : ℝ → ℝ → Fin m → ℝ} {p L : ℝ}
  (certificate : SharedAccuracyCertificateDraft.Certificate family q p L) (n : ℕ) (hn : certificate.threshold ≤ n) :
  ∃ projected, family.InitialProjection n q projected ∧ family.admitted n projected

SharedAccuracyCertificateDraft.Certificate.executed_bound.{u_1, u_2, u_3, u_4, u_5, u_6} {m : ℕ} {D : Type u_1}
  {Cell : Type u_2} {Face : Type u_3} {Point : Type u_4} {FacePoint : Type u_5} {Line : Type u_6}
  [MeasurableSpace Point] [TopologicalSpace Point] [MeasurableSpace FacePoint]
  {f : NumStability.DirectionalLine.LineFamily m} {q : ℝ → ℝ → Fin m → ℝ} {p L : ℝ}
  (certificate : SharedAccuracyCertificateDraft.Certificate f q p L)
  {data : NumStability.FiniteCoordinate.PhysicalData D Cell Face Point FacePoint m}
  {coord : NumStability.FiniteCoordinate.LineCoordinates D Cell Face Line}
  {family : D → Line → NumStability.DirectionalLine.LineFamily m}
  (realization : NumStability.FiniteCoordinate.LineRealization data coord family) (d : D) (cell : Cell)
  (hf : family d (coord.cellLine d cell) = f) (hn : certificate.threshold ≤ realization.level d (coord.cellLine d cell))
  (projected current : Cell → Fin m → ℝ)
  (hproj :
    f.InitialProjection (realization.level d (coord.cellLine d cell)) q
      (coord.extract d (coord.cellLine d cell) projected))
  (hadmit : realization.Admitted d current) {E : ℝ} (hE : 0 ≤ E) (herr : ∀ (c : Cell), ‖current c - projected c‖ ≤ E) :
  ‖NumStability.FiniteCoordinate.advance data realization.rule d (realization.duration d) current cell -
        NumStability.finiteVolumeCellAverageOn (f.grid (realization.level d (coord.cellLine d cell)))
          (fun x => q x (realization.duration d)) (coord.cellIndex d cell)‖ ≤
    (1 + L * realization.duration d) * E +
      certificate.constant * realization.duration d * f.mesh (realization.level d (coord.cellLine d cell)) ^ p
